SELECT MSG_ID AS msgId, LANG_CD AS langCd, MSG_TYPE AS msgType, MSG_CONTENT AS msgContent, DESCRIPTION AS description, IS_USE AS isUse, DATE_FORMAT(CREATED_AT, '%Y-%m-%d %H:%i') AS createdAt, DATE_FORMAT(UPDATED_AT, '%Y-%m-%d %H:%i') AS updatedAt FROM com_message
AND (MSG_ID LIKE CONCAT('%', #{keyword}, '%') OR MSG_CONTENT LIKE CONCAT('%', #{keyword}, '%'))
AND LANG_CD = #{langCd}
AND MSG_TYPE = #{msgType}
ORDER BY MSG_ID ASC, LANG_CD ASC

mapper.update:
UPDATE com_message
SET MSG_TYPE    = #{msgType},
    MSG_CONTENT = #{msgContent},
    DESCRIPTION = #{description},
    IS_USE      = #{isUse}
WHERE MSG_ID = #{msgId} AND LANG_CD = #{langCd}

UPDATE com_message
SET IS_USE = #{isUse}
WHERE MSG_ID = #{msgId} AND LANG_CD = #{langCd}
